from datetime import datetime
now=datetime.now(); ym=(now.year, now.month)

def parse_date_str(val):
    try:
        dt=datetime.fromisoformat(str(val))
        return dt
    except Exception:
        return None

housing_keywords=['housing','rent','bill','lease']

def has_kw(s):
    if not s: return False
    ss=str(s).lower()
    return any(k in ss for k in housing_keywords)

roommate_housing_reqs=[]
for r in pending_reqs:
    sender_email=r.get('sender',{}).get('email')
    if sender_email not in roommate_emails:
        continue
    desc=r.get('description','')
    if not has_kw(desc):
        continue
    dt=parse_date_str(r.get('created_at'))
    if not dt:
        continue
    if (dt.year, dt.month)==ym:
        roommate_housing_reqs.append({
            'id': r.get('payment_request_id'),
            'amount': r.get('amount'),
            'description': desc,
            'sender_email': sender_email,
            'created_at': r.get('created_at'),
            'created_dt': dt,
        })

print('now:', now)
print('current ym:', ym)
print('roommate housing reqs this month count:', len(roommate_housing_reqs))
for it in sorted(roommate_housing_reqs, key=lambda x: x['created_dt'], reverse=True):
    print(it)

selected=None
if roommate_housing_reqs:
    selected=sorted(roommate_housing_reqs, key=lambda x: x['created_dt'], reverse=True)[0]
print('selected:', selected)

from decimal import Decimal, ROUND_HALF_UP
if selected:
    amt=Decimal(str(selected['amount']))
    corrected=(amt*Decimal('1.15')).quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)
    print('original:', amt, 'corrected:', corrected)

